CREATE OR REPLACE PROCEDURE public.sp_update_consent_signer(IN p_id uuid, IN p_tenant_id uuid, IN p_signing_status character varying, IN p_token_hash character varying, IN p_token_expires_at timestamp with time zone, IN p_invitation_sent_count integer, IN p_last_invitation_sent_at timestamp with time zone, IN p_last_opened_at timestamp with time zone, IN p_signed_at timestamp with time zone, IN p_signature_legal_name character varying, IN p_signature_intent_text text, IN p_signature_ip_address character varying, IN p_signature_user_agent text)  LANGUAGE plpgsql AS $procedure$ BEGIN     UPDATE consent_signers     SET signing_status = p_signing_status,         token_hash = p_token_hash,         token_expires_at = p_token_expires_at,         invitation_sent_count = p_invitation_sent_count,         last_invitation_sent_at = p_last_invitation_sent_at,         last_opened_at = p_last_opened_at,         signed_at = p_signed_at,         signature_legal_name = p_signature_legal_name,         signature_intent_text = p_signature_intent_text,         signature_ip_address = p_signature_ip_address,         signature_user_agent = p_signature_user_agent     WHERE id = p_id AND tenant_id = p_tenant_id; END; $procedure$ ;
